const resposta = $input.item.json;

// 1. Validar a estrutura da resposta da API
const conteudo = resposta?.choices?.[0]?.message?.content;

if (typeof conteudo !== "string" || !conteudo.trim()) {
  throw new Error("A API não retornou um conteúdo válido.");
}

// 2. Converter o JSON retornado pela IA
let classificacao;

try {
  classificacao = JSON.parse(conteudo);
} catch (error) {
  throw new Error(
    "A IA retornou um JSON inválido: " + error.message
  );
}

// 3. Validar se a resposta é um objeto
if (
  typeof classificacao !== "object" ||
  classificacao === null ||
  Array.isArray(classificacao)
) {
  throw new Error("A classificação retornada não é um objeto válido.");
}

// 4. Definir valores permitidos
const categorias = [
  "cobranca",
  "suporte_tecnico",
  "duvida_produto",
  "cancelamento",
  "entrega_pedido",
  "elogio",
  "outros"
];

const urgencias = ["alta", "media", "baixa"];

const sentimentos = ["positivo", "neutro", "negativo"];

// 5. Normalizar os campos de classificação
const categoria = classificacao.categoria?.trim().toLowerCase();
const urgencia = classificacao.urgencia?.trim().toLowerCase();
const sentimento = classificacao.sentimento?.trim().toLowerCase();

// 6. Validar os valores
if (!categorias.includes(categoria)) {
  throw new Error(`Categoria inválida: ${categoria}`);
}

if (!urgencias.includes(urgencia)) {
  throw new Error(`Urgência inválida: ${urgencia}`);
}

if (!sentimentos.includes(sentimento)) {
  throw new Error(`Sentimento inválido: ${sentimento}`);
}

// 7. Validar os campos textuais
const resumo = classificacao.resumo;
const rascunhoResposta = classificacao.rascunho_resposta;

if (typeof resumo !== "string" || !resumo.trim()) {
  throw new Error("Resumo ausente ou inválido.");
}

if (
  typeof rascunhoResposta !== "string" ||
  !rascunhoResposta.trim()
) {
  throw new Error("Rascunho de resposta ausente ou inválido.");
}

// 8. Recuperar os dados originais do Gmail
const dadosOriginais = $("Edit Fields (Gmail)").item.json;

// 9. Retornar os dados combinados
return {
  json: {
    ...dadosOriginais,
    categoria,
    urgencia,
    sentimento,
    resumo: resumo.trim(),
    rascunho_resposta: rascunhoResposta.trim()
  }
};
